        /// </summary>
        /// <remarks>
        /// If <paramref name="instance" /> is <c>null</c>, calling this method will only unregister all existing callbacks but not register any new callbacks.
        /// </remarks>
        /// <seealso cref="ActionlessActions.AddCallbacks(IActionlessActions)" />
        /// <seealso cref="ActionlessActions.RemoveCallbacks(IActionlessActions)" />
        /// <seealso cref="ActionlessActions.UnregisterCallbacks(IActionlessActions)" />
        public void SetCallbacks(IActionlessActions instance)
        {
